type MigrationJournal={schemaVersion:1;planId:string;planDigest:string;workspace:string;status:'applying'|'applied'|'rolling-back'|'rolled-back';checkpoint?:CheckpointReceipt;entries:Record<string,JournalEntry>;dbChanges:Array<{entityId:string;entityKind:'export';oldReference:string;newReference:string;beforeRevision:number;afterRevision?:number;status:'pending'|'applied'|'rolled-back'}>;updatedAt:string};
type MigrationOptions={isWorkspaceIdle:()=>boolean|Promise<boolean>;isOwnerIdle:(owner:StorageOwner)=>boolean|Promise<boolean>;checkpoint:(planId:string)=>Promise<CheckpointReceipt>;freeBytes?:()=>number;afterCopy?:(entry:MigrationEntry)=>void|Promise<void>;afterRelocateBeforeJournalCommit?:(entry:MigrationEntry)=>void|Promise<void>};

const UUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const HASH=/^[a-f0-9]{64}$/;
const yieldLoop=()=>new Promise<void>(resolve=>setImmediate(resolve));
function safeRelative(value:unknown){if(typeof value!=='string'||!value||value.includes('\\')||value.includes(':')||value.startsWith('/')||value.split('/').some(part=>{const deviceBase=part.split('.')[0].replace(/[. ]+$/g,'');return !part||part==='.'||part==='..'||/^(CON|PRN|AUX|NUL|COM[1-9¹²³]|LPT[1-9¹²³])$/i.test(deviceBase)||/[<>"|?*\u0000-\u001f]/.test(part)||/[. ]$/.test(part);}))throw new Error('Migration path is not a safe normalized workspace-relative path.');return value;}
function pathFor(root:string,relative:string){const clean=safeRelative(relative),result=path.resolve(root,...clean.split('/'));if(!isPathWithin(root,result))throw new Error('Migration path escapes the workspace.');return result;}
