async function allEntities(store:AtelierStore,kind:string){const rows:Entity[]=[];for(let offset=0;offset<100000;offset+=500){const page=store.list({kind:kind as Entity['kind'],limit:500,offset});rows.push(...page);if(page.length<500)break;await yieldLoop();}return rows;}
