function planDigest(plan:StorageMigrationPlan){const clone={...plan,createdAt:''};return crypto.createHash('sha256').update(JSON.stringify(clone)).digest('hex');}
function signedEnvelope(store:AtelierStore,value:unknown){const payload=JSON.stringify(value);return JSON.stringify({payload,signature:store.signStorageRecord(payload)});}
