export function persistWorkspaceMigrationPlan(store:AtelierStore,plan:StorageMigrationPlan){const root=fs.realpathSync.native(store.root);validatePlanShape(plan,root);validatePlanComplete(plan);for(const entry of plan.entries)expectedPaths(store,plan,entry);const file=planFile(store,plan.planId);assertNoJunctions(root,file);if(fs.existsSync(file))throw new Error('Migration plan id already exists.');writeSigned(store,file,root,plan);return {planId:plan.planId,path:path.relative(root,file).replace(/\\/g,'/'),digest:planDigest(plan)};}
